namespace CF.Core.Code;

/// <summary>
/// The kind of value a property holds.
/// </summary>
public enum PropertyValueType
{
    /// <summary>
    /// A piece of text.
    /// </summary>
    Text,

    /// <summary>
    /// A whole number.
    /// </summary>
    Number,

    /// <summary>
    /// Either true or false.
    /// </summary>
    Boolean
}